/**
 * Rewrites the GLSL ES 1.00 shaders generated by ol's ShaderBuilder into
 * Vulkan-flavoured GLSL 450 that naga can translate to WGSL:
 *
 * - loose uniforms are gathered into one std140 block (identical in both
 *   stages, so they share a single uniform buffer), plus `u_ol_fbHeight`;
 * - `sampler2D` uniforms and parameters are split into texture + sampler
 *   (WGSL has no combined samplers); `texture2D(s, uv)` samples LOD 0;
 * - attributes / varyings get explicit locations;
 * - `gl_FragColor` becomes an output, `gl_FragCoord` is flipped to GL's
 *   bottom-left origin, and clip-space z is remapped from [-1, 1] to [0, 1].
 */

export interface VulkanShaders {
  vertex: string;
  fragment: string;
  /** Attribute name to vertex input location. */
  attributes: Map<string, number>;
  /** Attribute name to GLSL type (float, vec2, vec3, vec4). */
  attributeTypes: Map<string, string>;
  /** Non-sampler uniforms in block order: name and GLSL type. */
  uniforms: Array<{name: string; type: string; array?: string}>;
  /** Sampler uniform names, in binding order (texture = 1 + 2k, sampler = 2 + 2k). */
  samplers: string[];
}

export const FB_HEIGHT_UNIFORM = 'u_ol_fbHeight';

const PRECISION = '(?:(?:lowp|mediump|highp)\\s+)?';
const UNIFORM_RE = new RegExp(`^[ \\t]*uniform\\s+${PRECISION}(\\w+)\\s+(\\w+)\\s*(\\[[^\\]]+\\])?\\s*;[ \\t]*$`, 'gm');
const ATTRIBUTE_RE = new RegExp(`^[ \\t]*attribute\\s+${PRECISION}(\\w+)\\s+(\\w+)\\s*;[ \\t]*$`, 'gm');
const VARYING_RE = new RegExp(`^[ \\t]*varying\\s+${PRECISION}(\\w+)\\s+(\\w+)\\s*;[ \\t]*$`, 'gm');
const MAIN_RE = /\bvoid\s+main\s*\(\s*(?:void)?\s*\)/;

/**
 * Words that are plain identifiers in GLSL ES 1.00 but keywords in GLSL 450.
 * ol's style-derived names are always prefixed (`u_var_`, `a_prop_`), so only
 * ShaderBuilder's own helper names can collide; they get an `ol_` prefix.
 */
const RESERVED_450 = [
  'sample', 'smooth', 'flat', 'noperspective', 'centroid', 'patch', 'buffer', 'shared',
  'coherent', 'volatile', 'restrict', 'readonly', 'writeonly', 'subroutine', 'precise',
  'common', 'partition', 'active', 'filter', 'resource', 'input', 'output', 'superp',
];
const RESERVED_RE = new RegExp(`\\b(${RESERVED_450.join('|')})\\b`, 'g');

function stripCommon(src: string): string {
  return src
    .replace(/#ifdef\s+GL_FRAGMENT_PRECISION_HIGH[\s\S]*?#endif/g, '')
    .replace(/^[ \t]*#extension[^\n]*$/gm, '')
    .replace(/^[ \t]*#version[^\n]*$/gm, '')
    .replace(/^[ \t]*precision\s+\w+\s+\w+\s*;[ \t]*$/gm, '')
    .replace(/\/\/[^\n]*/g, '') // comments may contain reserved words
    .replace(RESERVED_RE, 'ol_$1');
}

interface Collected {
  body: string;
  uniforms: Array<{name: string; type: string; array?: string}>;
  samplers: string[];
}

function collectUniforms(src: string): Collected {
  const uniforms: Collected['uniforms'] = [];
  const samplers: string[] = [];
  const body = src.replace(UNIFORM_RE, (_m, type: string, name: string, array?: string) => {
    if (type === 'sampler2D') {
      samplers.push(name);
    } else {
      uniforms.push({name, type, array});
    }
    return '';
  });
  return {body, uniforms, samplers};
}

/** Splits combined samplers: parameters, texture2D() calls and bare uses. */
function splitSamplers(src: string, uniformSamplers: string[]): string {
  const names = new Set(uniformSamplers);
  // function parameters `sampler2D name`
  src = src.replace(/\bsampler2D\s+(\w+)/g, (_m, name: string) => {
    names.add(name);
    return `texture2D ${name}_t, sampler ${name}_s`;
  });
  for (const name of names) {
    src = src.replace(new RegExp(`\\btexture2D\\s*\\(\\s*${name}\\s*,`, 'g'), `ol_texture(${name}_t, ${name}_s,`);
    // remaining bare uses are call arguments
    src = src.replace(new RegExp(`\\b${name}\\b(?!_[ts]\\b)`, 'g'), `${name}_t, ${name}_s`);
  }
  return src;
}

const TEXTURE_HELPER = `
vec4 ol_texture(texture2D t, sampler s, vec2 uv) {
  return textureLod(sampler2D(t, s), uv, 0.0);
}
`;

function uniformBlock(uniforms: VulkanShaders['uniforms']): string {
  const members = uniforms.map((u) => `  ${u.type} ${u.name}${u.array ?? ''};`).join('\n');
  return `layout(set = 0, binding = 0, std140) uniform OlUniforms {\n${members}\n};\n`;
}

function samplerDecls(samplers: string[]): string {
  return samplers
    .map(
      (s, k) =>
        `layout(set = 0, binding = ${1 + 2 * k}) uniform texture2D ${s}_t;\n` +
        `layout(set = 0, binding = ${2 + 2 * k}) uniform sampler ${s}_s;\n`,
    )
    .join('');
}

export function toVulkanGlsl(vertexSrc: string, fragmentSrc: string): VulkanShaders {
  const v = collectUniforms(stripCommon(vertexSrc));
  const f = collectUniforms(stripCommon(fragmentSrc));

  // union of uniforms, vertex order first
  const uniforms: VulkanShaders['uniforms'] = [];
  const seen = new Set<string>();
  for (const u of [...v.uniforms, ...f.uniforms]) {
    if (!seen.has(u.name)) {
      seen.add(u.name);
      uniforms.push(u);
    }
  }
  uniforms.push({name: FB_HEIGHT_UNIFORM, type: 'float'});
  const samplers = [...new Set([...v.samplers, ...f.samplers])];
  const header = '#version 450\n' + uniformBlock(uniforms) + samplerDecls(samplers) + (samplers.length ? TEXTURE_HELPER : '');

  // vertex: attributes and varyings
  const attributes = new Map<string, number>();
  const attributeTypes = new Map<string, string>();
  const varyings = new Map<string, number>();
  let vertex = v.body
    .replace(ATTRIBUTE_RE, (_m, type: string, name: string) => {
      const loc = attributes.size;
      attributes.set(name, loc);
      attributeTypes.set(name, type);
      return `layout(location = ${loc}) in ${type} ${name};`;
    })
    .replace(VARYING_RE, (_m, type: string, name: string) => {
      const loc = varyings.size;
      varyings.set(name, loc);
      return `layout(location = ${loc}) out ${type} ${name};`;
    });
  vertex = splitSamplers(vertex, samplers).replace(MAIN_RE, 'void ol_main()');
  vertex =
    header +
    vertex +
    `
void main() {
  ol_main();
  gl_Position.z = (gl_Position.z + gl_Position.w) * 0.5;
}
`;

  let fragment = f.body.replace(VARYING_RE, (_m, type: string, name: string) => {
    let loc = varyings.get(name);
    if (loc === undefined) {
      loc = varyings.size;
      varyings.set(name, loc);
    }
    return `layout(location = ${loc}) in ${type} ${name};`;
  });
  fragment = splitSamplers(fragment, samplers)
    .replace(/\bgl_FragColor\b/g, 'ol_FragColor')
    .replace(/\bgl_FragCoord\b/g, 'ol_FragCoord')
    .replace(MAIN_RE, 'void ol_main()');
  fragment =
    header +
    'layout(location = 0) out vec4 ol_FragColor;\nvec4 ol_FragCoord;\n' +
    fragment +
    `
void main() {
  ol_FragCoord = vec4(gl_FragCoord.x, ${FB_HEIGHT_UNIFORM} - gl_FragCoord.y, gl_FragCoord.z, gl_FragCoord.w);
  ol_main();
}
`;

  return {vertex, fragment, attributes, attributeTypes, uniforms, samplers};
}
